"""Reproducible ownership / geometry audit and local tower-pool comparison."""
import json,struct,hashlib,html,base64,math
from pathlib import Path
out=Path('build/resort-blocks/paris')
raw=Path('build/geographic-strip/detailed.glb').read_bytes();n=struct.unpack_from('<I',raw,12)[0];gltf=json.loads(raw[20:20+n]);del raw
old=[n.get('name') for n in gltf['nodes'] if n.get('extras',{}).get('geographicOwner')=='eiffel' and 'mesh' in n]
assert not old,'Old Eiffel geometry must not render over the replacement'
geo=json.loads((out/'parisBlock-exterior.json').read_text());tower=[g for g in geo['meshes'] if g['source'].startswith('guest-eiffel')]
assert all(math.isfinite(v) for g in tower for p in g['vertices'] for v in p),'No invalid girder vertices'
ys=[p[1] for g in tower for p in g['vertices']];assert abs(max(ys)-164.9)<.05,'Tower height must match 541 ft source within rounding'
assert any('pool-loungers' in g['source'] for g in geo['meshes']),'Pool furniture must be permanently exterior'
interior=json.loads((out/'parisPool-interior.json').read_text());assert all(g['source'].startswith('anchor') for g in interior['meshes']),'No duplicated streamed pool furniture'
routes=json.loads((out/'route-audit.json').read_text());assert routes['city'] and not routes['failures']
report=dict(date='2026-10-06',oldEiffelVisibleMeshes=len(old),eiffelHeightM=round(max(ys),2),towerTriangles=sum(len(g['faces']) for g in tower),authoringTriangles=sum(len(g['faces']) for g in geo['meshes']),routeChecks=routes['checks'],routeFailures=len(routes['failures']),groundedCasinoApproach=routes['approachSweep'],measurements=json.loads((out/'tower-pool-measurements.json').read_text()),staticBatching='64 m exterior cells; Eiffel members grouped by structure/lattice/observation, not per beam or chair',limitations=['Tower intermediate sections, patio elevation and furniture locations photo-fitted, not surveyed','Pool water decorative; no swimming mechanics','Whole Paris resort architectural acceptance remains open'])
runtime=out/'tower-pool-runtime.json'
if runtime.exists():report['runtime']=json.loads(runtime.read_text())
(out/'tower-pool-validation.json').write_text(json.dumps(report,indent=2))
def img(p,label):
 p=Path(p)
 if not p.exists():return ''
 mime='image/jpeg' if p.suffix=='.jpg' else 'image/png'
 return '<figure><figcaption>'+html.escape(label)+'</figcaption><img src="data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()+'"></figure>'
rows=[('tools/resort-blocks/references/paris-eiffel-close-reference-2026-10-06.png','REFERENCE · Creator close view for the shape retry'),(out/'game-eiffel-retry.jpg','GAME · Revised pier profiles and upper arch'),('tools/resort-blocks/references/paris-eiffel-rejected-2026-10-06.png','REJECTED · Thin piers and oversized upper opening'),(out/'tower-base-review.png','EXPORT · Revised geometry under neutral light'),('tools/resort-blocks/references/paris-tower-pool-earth-2026-10-06.png','REFERENCE · Creator Google Earth image; image date unknown'),(out/'game-tower-pool.jpg','HISTORICAL · Earlier tower / pool overview; tower superseded'),('tools/resort-blocks/references/paris-tower-pool-before-2026-10-06.png','BEFORE · Creator screenshot of previous geometry'),(out/'game-pool-aerial.jpg','GAME · Outdoor pool deck visible from above'),(out/'tower-pool-review.png','EXPORT · Neutral daylight / actual exported game mesh'),(out/'pool-aerial-review.png','EXPORT · Pool basin, radial paving, cabanas and seating'),(out/'game-observation.jpg','HISTORICAL · Unchanged observation gallery, earlier lift test'),(out/'game-pool-ground.jpg','GAME · Reachable pool terrace')]
page='''<!doctype html><meta charset="utf-8"><title>Paris Eiffel and pool · 2026-10-06</title><style>body{margin:32px;background:#182124;color:#edf1ed;font:17px/1.5 system-ui}h1{font-size:32px}p{max-width:1100px}main{display:grid;grid-template-columns:1fr 1fr;gap:24px}figure{margin:0}figcaption{margin:10px 0;color:#b2d9d1}img{width:100%}a{color:#b2d9d1}pre{white-space:pre-wrap}@media(max-width:850px){main{display:block}}</style><h1>Paris · Eiffel tower and Pool à Paris</h1><p>Creator rejected the previous tower shape. This retry broadens the piers into the restaurant platform, reduces their outward sweep, closes the oversized second-stage opening with an arched apron, and replaces hairline main chords with flange/web girders and heavier diagonals. Its lattice uses a regular grid. The close comparison is the evidence for this pass; older pool captures below document unchanged pool geometry. Its existing two-way lift keeps the same landings. The pool deck now has inset corner urns, radial paving, 159 loungers, nine white cabanas and a planted perimeter. Furnishings are permanent exterior geometry with spatial LOD.</p><p>Old Eiffel render meshes, collision and shadow proxies are removed. Photographs are visual references; the game meshes and materials are originally authored. These views use comparable directions, not a calibrated photogrammetric camera. The pool stair was shifted 2m west and the ground approach routed around the wider footing; collision remains enabled.</p><main>'''+''.join(img(*r) for r in rows)+'''</main><h2>References</h2><p><a href="https://www.schuff.com/project/eiffel-tower-at-paris-las-vegas/">Schuff Steel, fabricator</a> and <a href="https://newsroom.caesars.com/files/doc_downloads/2025/04/Paris-Las-Vegas-Fact-Sheet_April-2025-FINAL.pdf">Caesars April 2025 fact sheet</a>: 541 ft total height, 460 ft viewing gallery. <a href="https://www.highperformancecoatings.org/project-profiles/eiffel-tower-at-paris-las-vegas">Coatings project photograph</a>: steel profiles and tone. <a href="https://www.flickr.com/photos/97585109%40N00/5642014764">2010 observation-gallery detail</a>: cage and brackets. <a href="https://x.com/ParisVegas/status/1391850792055971842">Operator pool aerial, 2021</a>: radial deck, inset pool corners and furniture character. <a href="https://www.caesars.com/content/dam/empire/plv/property/rideshare/paris-las-vegas-map.pdf">Operator map</a>: third-level pool.</p><h2>Remaining refinements</h2><p>Intermediate steel dimensions and individual furniture placement remain approximations. The hotel tower, Opera pavilion, real interior arrival hall, fine sculpture and complete resort boundary remain subject to the open Paris checklist. Pool water is decorative, without swimming. This correction does not mark the resort complete.</p><h2>Validation</h2><pre>'''+html.escape(json.dumps(report,indent=2))+'''</pre>'''
(out/'tower-pool-proof.html').write_text(page);print(json.dumps(report,indent=2))
